CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant_settings (tenant_id uuid PRIMARY KEY REFERENCES tenants(id), approval_mode boolean NOT NULL DEFAULT false, confidence_threshold double precision NOT NULL DEFAULT 0.85 CHECK(confidence_threshold BETWEEN 0 AND 1), forbidden_categories jsonb NOT NULL DEFAULT '["refund","account_theft","sanction"]', allowed_domains jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id), email text NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), CHECK((role='platform_admin' AND tenant_id IS NULL) OR (role IN ('customer','agent','tenant_admin') AND tenant_id IS NOT NULL)));
CREATE UNIQUE INDEX users_tenant_email ON users(tenant_id,lower(email)) WHERE tenant_id IS NOT NULL;
CREATE UNIQUE INDEX users_platform_email ON users(lower(email)) WHERE tenant_id IS NULL;
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id), email text NOT NULL, ip_hash text NOT NULL, success boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX login_attempts_lookup ON login_attempts(email,ip_hash,created_at);
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), customer_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,customer_id) REFERENCES users(tenant_id,id));
CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), customer_id uuid NOT NULL, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')), version integer NOT NULL DEFAULT 1 CHECK(version>0), auto_reply_count integer NOT NULL DEFAULT 0 CHECK(auto_reply_count BETWEEN 0 AND 1), escalated_at timestamptz, escalation_reason text, assignee_id uuid, conversation_id uuid UNIQUE, resolved_at timestamptz, customer_confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,customer_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,assignee_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE INDEX tickets_customer ON tickets(tenant_id,customer_id,created_at);
CREATE TABLE ai_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), ticket_id uuid, conversation_id uuid, message_id uuid NOT NULL, pipeline_version text NOT NULL DEFAULT 'v1', idempotency_key text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','succeeded','failed')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), max_attempts integer NOT NULL DEFAULT 3 CHECK(max_attempts>0), available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,idempotency_key), CHECK((ticket_id IS NOT NULL)::int+(conversation_id IS NOT NULL)::int=1), FOREIGN KEY(tenant_id,ticket_id) REFERENCES tickets(tenant_id,id), FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE INDEX ai_jobs_claim ON ai_jobs(status,available_at,lease_until);
CREATE TABLE ticket_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), ticket_id uuid NOT NULL, author_id uuid, role text NOT NULL CHECK(role IN ('customer','agent','tenant_admin','ai')), body text NOT NULL, visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','internal')), created_at timestamptz NOT NULL DEFAULT now(), source_job_id uuid UNIQUE, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,ticket_id) REFERENCES tickets(tenant_id,id), FOREIGN KEY(tenant_id,author_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,source_job_id) REFERENCES ai_jobs(tenant_id,id));
CREATE TABLE conversation_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), conversation_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('customer','ai')), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), source_job_id uuid UNIQUE, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id), FOREIGN KEY(tenant_id,source_job_id) REFERENCES ai_jobs(tenant_id,id));
CREATE TABLE ai_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), ticket_id uuid, conversation_id uuid, job_id uuid NOT NULL UNIQUE, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','succeeded','failed')), result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((ticket_id IS NOT NULL)::int+(conversation_id IS NOT NULL)::int=1), FOREIGN KEY(tenant_id,ticket_id) REFERENCES tickets(tenant_id,id), FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id), FOREIGN KEY(tenant_id,job_id) REFERENCES ai_jobs(tenant_id,id));
CREATE TABLE ai_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), ticket_id uuid NOT NULL, job_id uuid NOT NULL UNIQUE, body text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','sent','rejected')), version integer NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,ticket_id) REFERENCES tickets(tenant_id,id), FOREIGN KEY(tenant_id,job_id) REFERENCES ai_jobs(tenant_id,id));
CREATE TABLE kb_articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), slug text NOT NULL, title text NOT NULL, body text NOT NULL, category text NOT NULL, published boolean NOT NULL DEFAULT true, source_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,slug));
CREATE INDEX kb_tenant_category ON kb_articles(tenant_id,category);
CREATE INDEX kb_search ON kb_articles USING gin(to_tsvector('simple', title || ' ' || body));
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id), actor_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_tenant_created ON audit_log(tenant_id,created_at);
-- message_id is polymorphic. A deferred trigger validates the precise parent and tenant
-- at commit, permitting ticket/message/job creation in one transaction.
CREATE FUNCTION validate_job_message() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.ticket_id IS NOT NULL THEN
   IF NOT EXISTS (SELECT 1 FROM ticket_messages WHERE id=NEW.message_id AND tenant_id=NEW.tenant_id AND ticket_id=NEW.ticket_id) THEN RAISE EXCEPTION 'job message does not belong to ticket' USING ERRCODE='23503'; END IF;
 ELSE
   IF NOT EXISTS (SELECT 1 FROM conversation_messages WHERE id=NEW.message_id AND tenant_id=NEW.tenant_id AND conversation_id=NEW.conversation_id) THEN RAISE EXCEPTION 'job message does not belong to conversation' USING ERRCODE='23503'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER ai_jobs_message_fk AFTER INSERT OR UPDATE ON ai_jobs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_job_message();
